/** Get File By Id */
export function useGetFileById(options?: Omit<UseMutationOptions<Blob, ApiError, string>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const result = await api.files.getFileById(id);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: (data, variables, onMutateResult, context) => {
      queryClient.invalidateQueries({ queryKey: filesKeys.all });
      options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}

